    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  assert.equal(result.ok, true);
  const updated = addLine(result.value, { sku: 'INVALID-SKU', qty: 1 });

  assert.equal(updated.ok, false);
  assert.equal(updated.error, 'UNKNOWN_SKU');
});

test('addLine: returns NOT_DRAFT if invoice is not draft', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2025-10-07',
    status: 'sent',
    lines: [{ sku: 'DEV-HOUR', qty: 5, name: 'Development (hour)', unitPrice: 9500, vatRate: 21 }],
  };

  const updated = addLine(invoice, { sku: 'LOGO-PACK', qty: 1 });

  assert.equal(updated.ok, false);
  assert.equal(updated.error, 'NOT_DRAFT');
});

test('addLine: does not mutate original invoice', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  assert.equal(result.ok, true);
  const invoiceCopy = JSON.parse(JSON.stringify(result.value));

  addLine(result.value, { sku: 'LOGO-PACK', qty: 1 });

