test('renderInvoiceText: shows subtotal and discount rows when applicable', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 10, discountPercent: 10 },
      { sku: 'LOGO-PACK', qty: 1, discountPercent: 20 },
    ],
  });

  assert.equal(result.ok, true);
  const text = renderInvoiceText(result.value);
  const lines = text.split('\n');

  assert.match(text, /Subtotal: €950\.00/);
  assert.match(text, /Discount: -€265\.00/);
  assert.match(text, /Total: €685\.00/);
});

test('renderInvoiceText: calculates correct totals with multiple discounts', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 5, discountPercent: 10 },
      { sku: 'COPY-HOUR', qty: 4, discountPercent: 25 },
    ],
  });

  assert.equal(result.ok, true);
  const text = renderInvoiceText(result.value);

  const expectedSubtotal = 5 * 9500 + 4 * 6000;
  const expectedDiscount = Math.round((47500 * 10) / 100) + Math.round((24000 * 25) / 100);
  const expectedTotal = expectedSubtotal - expectedDiscount;

  assert.match(text, new RegExp(`Total: .*€`));
});

